"""Tests for olala_quant.budget: projected sizes from the real header, generated by script."""

import json
import math
from pathlib import Path

import pytest

from olala_quant import budget

HEADER = Path(__file__).parent / "data" / "olala_header.json"


def test_projection_matches_independent_arithmetic() -> None:
    table = budget.project_all(HEADER)
    by_key = {(r["recipe"], r["ignore"]): r for r in table["rows"]}
    assert set(by_key) == {("fp8", "none"), ("fp8", "I"), ("nvfp4", "none"), ("nvfp4", "I")}
    total = 6_773_124_360
    assert table["source"]["total_params"] == total
    raw = json.loads(HEADER.read_text())
    expected_bytes = sum(
        math.prod(v["shape"]) * {"BF16": 2, "F32": 4}[v["dtype"]]
        for k, v in raw.items()
        if k != "__metadata__"
    )
    assert table["source"]["source_bytes"] == expected_bytes
    for row in by_key.values():
        assert row["bits_per_weight"] == pytest.approx(row["output_bytes"] * 8 / total)
    assert by_key[("fp8", "none")]["n_quantized"] == 259
    assert by_key[("fp8", "I")]["n_quantized"] == 232
    assert by_key[("fp8", "I")]["n_ignored_quantizable"] == 27
    # sizes ordered as expected: ignoring layers keeps more bytes; nvfp4 < fp8
    assert by_key[("nvfp4", "none")]["output_bytes"] < by_key[("nvfp4", "I")]["output_bytes"]
    assert by_key[("nvfp4", "I")]["output_bytes"] < by_key[("fp8", "none")]["output_bytes"]
    assert by_key[("fp8", "none")]["output_bytes"] < table["source"]["source_bytes"]


def test_cli_writes_json(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    out = tmp_path / "budget.json"
    assert budget.main(["--header", str(HEADER), "--out", str(out)]) == 0
    data = json.loads(out.read_text())
    assert data["rows"]
    assert "bits per weight" in capsys.readouterr().out
